 const assetPool=[...new Map(done.flatMap(j=>j.references||[]).filter(r=>r.available!==false&&r.kind==='image').map(r=>[r.src,r])).values()].slice(0,25);
 if(!assetPool.length)assetPool.push({src:'assets/coast.jpg',name:'海岸示例',kind:'image',previewExample:true},{src:'assets/forest.jpg',name:'森林示例',kind:'image',previewExample:true});
 const drafts=new Map(),initials=new Map(),contextDrafts=new Map();
 let activeContext=null,selectedAssets=new Set(),taskFilter='全部',taskQuery='',workFilter='全部',workQuery='',timeFilter='全部时间',componentFilter='全部',workNames=new Map(),runTimer=null,runToken=0;
 const preferences={reduce:matchMedia('(prefers-reduced-motion:reduce)').matches};
 function draft(scene){if(!drafts.has(scene)){const id=workflowMap[scene],w=sources.get(id),s=sample(id),d={prompt:s.job?.prompt||({outfit:'保留人物与背景，换上服装参考图中的衣服。',outpaint:'自然延续原图的场景、光线与材质。',camera:'保留人物、服装与场景，改变拍摄角度。',video:'将天空改为日落暖色，保留原片动作与声音。'}[scene]||''),negative:s.job?.negative||'',refs:(w?.interface?.media||[{id:'video',kind:'video',label:'原视频'}]).map((m,i)=>{const refs=s.refs.filter(r=>r.kind===m.kind);const r=m.kind==='video'?s.refs.find(r=>r.kind==='video'):refs[i];return r?{...r,catalogSlot:m.id}:null}),catalogValues:{},catalogSeedModes:{},stage:'ready',comparison:false,padRatio:'',start:2,end:5,videoDuration:10};if(scene==='multi'&&!d.refs.some(Boolean)){const ref=sample('local-card-14').refs.find(r=>r.kind==='image');if(ref)d.refs=[{...ref,catalogSlot:w.interface.media[0].id}];}if(scene==='video'){d.refs=[{kind:'video',src:'assets/award-film-10s.mp4',name:'原站 10 秒示例片段',catalogSlot:'video'}];}for(const f of w?.interface?.controls||[]){const value=s.job?.settings?.[f.id]??s.job?.settings?.[f.key];if(value!==undefined){d.catalogValues[f.id]=value;if(f.kind==='seed')d.catalogSeedModes[f.id]='fixed';}}drafts.set(scene,d);initials.set(scene,deep(d));}return drafts.get(scene)}
