 function taskCard(t){const s=sample(t.id),origin=s.refs.find(r=>r.kind==='image'),out=s.out;let visual;if(origin&&out?.type==='image')visual=`${img(origin.src,'输入示例')}${img(out.src,'历史输出示例')}<span class="flow-arrow">→</span><span class="visual-label">原图</span><span class="visual-label right">历史结果</span>`;else if(t.scene==='multi')visual=`${miniCameraArt()}<span class="visual-label">机位示意</span>`;else if(out?.type==='image')visual=`${img(out.src,'历史结果')}<span class="visual-label">历史结果</span>`;else visual=taskCover(sources.get(t.id)||{id:t.id,name:t.title,category:t.scene==='video'?'视频编辑与人物替换':'文字生图'});return `<button class="task-card" data-nav="${t.scene}"><div class="task-visual ${origin&&out?.type==='image'?'pair':''}">${visual}</div><div class="task-text"><strong>${t.title}</strong><p>${t.desc}</p><div class="between"><span class="pill">${t.scene==='create'?'自由创作入口':status(t.id)}</span><span class="tiny-icon">↗</span></div></div></button>`}
