 function home(){return `<div class="page">${header('今天，想做点什么？','选一个任务，放入素材就可以开始。',button(I('spark')+' 自由创作','data-nav="create"','subtle'))}<div class="home-task-grid">${taskDefs.map(taskCard).join('')}</div><div class="quick-start">${I('image')}<div><strong>已有素材，还没决定怎么做？</strong><p>先选图片或视频，再选择适合它的操作。</p></div>${button('从素材开始 →','data-nav="assets"')}</div>${done.length?`<div class="section-heading between"><h2>继续上次的创作</h2>${button('全部作品 →','data-nav="works"','subtle')}</div><div class="recent-strip">${taskDefs.filter(t=>completed(t.id)).slice(0,3).map(t=>`<button class="recent-preview" data-nav="${t.scene}">${img(sampleImage(t.id),t.title)}<span><strong>${t.title}</strong><small>${dateLabel(completed(t.id).started)}</small></span></button>`).join('')}</div>`:''}</div>`}
 function tasks(){return `<div class="page">${header('创作工具','按你想完成的事选择工具。',`<input type="search" data-task-search placeholder="搜索换衣、扩图或模型名称" aria-label="搜索创作工具" value="${esc(taskQuery)}">`)}<div class="filter-row">${['全部','图片编辑','视频创作','图片生成'].map(t=>button(t,`data-task-filter="${t}"`,taskFilter===t?'active':'')).join('')}${button('全部工作流版本','data-all-versions','subtle')}</div><p class="status-note"><i></i>这里看布局和操作；有历史作品也不等于效果已通过验收。</p><div class="task-list-grid" id="task-list">${filteredTaskCards()}</div></div>`}
 function filteredTaskCards(){const list=taskDefs.filter(t=>(taskFilter==='全部'||t.category===taskFilter)&&(!taskQuery||[t.title,t.desc,sources.get(t.id)?.name].join(' ').toLowerCase().includes(taskQuery.toLowerCase())));return list.map(taskCard).join('')||'<p class="empty-state">没有匹配的工具。试试“换衣”或“扩图”。</p>'}
