 function translatedField(d,f){const field={...f};if(f.key==='megapixels')field.label='像素总量';if(f.kind==='ratio'&&f.options)field.options=f.options.map(o=>{const val=String(o?.value??o),ratio=val.match(/\d+:\d+/)?.[0];return ratio?{value:val,label:ratio+' '+({'1:1':'方形','16:9':'横屏','9:16':'竖屏','4:3':'横图','3:4':'竖图','2:3':'人像','3:2':'照片','21:9':'宽屏'}[ratio]||'')}:o});if(f.kind==='task')return `<div class="catalog-field"><label>创作方式</label><div class="code-display">${I('video')}<strong>参考图生成视频</strong><small>此流程的当前模式</small></div><input type="hidden" data-catalog-field="${esc(f.id)}" value="${esc(controlValue(d,f))}"><small>根据参考图和文字生成；沿用源图的 r2v。</small></div>`;let html=controlField(d,field);if(f.key==='megapixels')html=html.replaceAll('百万像素','像素总量（MP）');if(f.key==='megapixels')html+=`<small class="mp-explanation" data-mp-explanation>${Number(controlValue(d,f))*100} 万像素 · 表示像素总量，不等于画质档位</small>`;return html}
