 function seedBlock(w,d){const seeds=w.interface.controls.filter(f=>f.kind==='seed');return `<div class="control-context" ${context('seed-'+route(),w,d)}>${seedControls(seeds,d,{compact:true,showTitle:seeds.length>1}).replaceAll('每次随机','每次不同').replaceAll('固定种子','固定本次')}</div>`}
 function guideBlock(w,d,kind){const key='guide-'+route();return `<div class="control-context guide-context" ${context(key,w,d)}>${catalogCommonPanel({...w,interface:{...w.interface,controls:w.interface.controls.filter(f=>f.kind===kind)}},d)}</div>`}
 function trimMarkup(d){if(!d.refs[0])return mediaSlot({id:'video',kind:'video',label:'原视频'},0,d,'video');return `<div class="between" style="margin-bottom:10px"><small>${esc(d.refs[0].name||'原视频')}</small><div class="row">${button('替换视频','data-upload-slot="0"','subtle')}${button('移除','data-remove-slot="0"','subtle')}</div></div><input type="file" accept="video/*" data-file-slot="0" hidden><video class="source-video" id="preview-source-video" src="${esc(d.refs[0]?.src||'assets/award-film-10s.mp4')}" controls muted playsinline preload="metadata"></video><div class="trim-track" style="--start:${d.start/d.videoDuration*100}%;--end:${d.end/d.videoDuration*100}%"><div class="trim-selection"></div><input type="range" aria-label="片段起点" data-trim="start" min="0" max="${d.videoDuration}" step="0.01" value="${d.start}"><input type="range" aria-label="片段终点" data-trim="end" min="0" max="${d.videoDuration}" step="0.01" value="${d.end}"></div><div class="trim-readouts"><label>起点<input aria-label="片段起点秒数" data-trim-number="start" type="number" step="0.01" min="0" max="${d.videoDuration}" value="${d.start}"></label><label>终点<input aria-label="片段终点秒数" data-trim-number="end" type="number" step="0.01" min="0" max="${d.videoDuration}" value="${d.end}"></label></div><div class="between trim-summary"><span id="trim-summary">选取 ${d.start.toFixed(2)}–${d.end.toFixed(2)} 秒 · 共 ${(d.end-d.start).toFixed(2)} 秒</span>${button('播放选区','data-play-trim','subtle')}</div>`}
 function editor(scene){const d=draft(scene),id=workflowMap[scene],w=sources.get(id),t=taskDefs.find(t=>t.scene===scene),slots=w?.interface.media||[{id:'video',kind:'video',label:'原视频'}];let form='';
 if(scene==='video')form+=section('原视频与处理片段',trimMarkup(d));else form+=section(scene==='outfit'?'需要的素材':'原始素材',`<div class="media-slots ${slots.length===1?'one':''}">${slots.map((m,i)=>mediaSlot(m,i,d,scene)).join('')}</div>`);
 if(scene==='outpaint')form+=section('扩成什么画幅？',`<div class="filter-row">${['16:9','9:16','1:1'].map(r=>button(r,`data-pad-ratio="${r}"`,d.padRatio===r?'active':'')).join('')}</div>${guideBlock(w,d,'outpaint')}`,'画幅示意');
 if(scene==='camera'||scene==='multi')form+=section('机位设置',guideBlock(w,d,'camera'),'参数示意');
 if(scene!=='multi')form+=section(scene==='outfit'?'想怎样调整衣服？':scene==='outpaint'?'新增区域的内容':scene==='video'?'这段视频要改什么？':'补充要求',`<textarea data-prompt aria-label="修改要求" rows="3" placeholder="直接描述要修改的内容">${esc(d.prompt)}</textarea>`,'可直接修改');
 if(scene==='video'){const liveW=live.find(x=>x.id==='bernini-edit');const edge=liveW?.fields.find(x=>x.key==='long_side');form+=section('输出尺寸',`<div class="filter-row">${(edge?.options||[384,512,768,1024]).map(n=>button(n+' px',`data-video-edge="${n}" aria-pressed="${(d.videoEdge||1024)===n}"`)).join('')}</div><small>输出最长边 · 原视频比例保持不变</small>`);form+=section('变化方式（种子）',`<div class="wf-options">${button('每次不同','data-video-seed="random" aria-pressed="'+(d.seedMode!=='fixed')+'"')}${button('固定本次','data-video-seed="fixed" aria-pressed="'+(d.seedMode==='fixed')+'"')}</div><input style="width:100%;margin-top:8px" type="number" data-video-seed-number aria-label="固定种子值" value="${d.seed||424242}" min="0" step="1" ${d.seedMode==='fixed'?'':'disabled'}>`)}
 else {const rest=w.interface.controls.filter(f=>!['camera','outpaint','seed'].includes(f.kind));if(rest.length)form+=section('输出设置',realFields(w,d,f=>!['camera','outpaint'].includes(f.kind)));form+=section('变化方式（种子）',seedBlock(w,d));}
 if(scene==='video'||w?.interface.texts.some(t=>t.role==='negative'))form+=section('不希望出现的内容',`<textarea class="negative" data-negative aria-label="不希望出现的内容" rows="2" placeholder="选填，例如：水印、文字">${esc(d.negative)}</textarea>`,'选填');
 const states=[['ready','正常'],['empty','缺素材'],['running','生成中'],['failed','取回失败'],['done','完成']];
 return `<div class="editor-page"><div class="editor-top between"><div class="breadcrumb">${button('← 创作工具','data-nav="tasks"')}<span>/</span><span>${t.title}</span></div><div class="state-strip"><span>试试页面提醒</span>${states.map(([v,l])=>button(l,`data-stage="${v}"`,d.stage===v?'active':'')).join('')}</div></div><div class="editor-grid"><section class="edit-panel"><header class="edit-head between"><div><h1>${t.title}</h1><p>${t.desc}</p></div>${button(I('more')||'···','data-source-info aria-label="查看此工具来源"','subtle')}</header><div class="edit-scroll">${form}</div><footer class="edit-footer"><p class="validation-summary" id="validation-summary"></p><div class="between">${button('恢复初始设置','data-reset-draft','subtle')}${button(I('spark')+` ${scene==='video'?'演示生成片段':scene==='multi'?'演示生成 9 个视角':'演示生成 1 张'} →`,'data-generate','primary')}</div></footer></section><section class="result-panel"><header class="result-head"><strong>${scene==='outpaint'?'画幅与结果':'生成作品'}</strong><span class="pill">${d.stage==='running'?'状态演示':sample(workflowMap[scene]).out?'本机历史示例':'参数演示'}</span></header><div class="result-body" id="result-content">${resultContent(scene)}</div></section></div></div>`}
 function outputMarkup(scene){const d=draft(scene),s=sample(workflowMap[scene]),o=s.out;if(!o)return `<div class="result-empty">${I('image')}<strong>生成后，在这里查看结果</strong><p class="muted small">当前展示操作设计，未调用模型。</p></div><div class="result-layout-example"><small>生成后可用的操作 · 这里只看摆放方式</small><div class="result-actions">${button('与原图对比','disabled')}${button(I('download')+' 下载','disabled')}${button('继续修改','disabled','primary')}</div><p>恢复原来的输入，或把这一版接着改。</p></div>`;if(d.comparison&&o.type==='image'&&s.refs.find(r=>r.kind==='image')){const original=s.refs.find(r=>r.kind==='image');return `<div class="compare-frame" style="--compare:50%">${img(o.src,'历史生成结果')}<div class="compare-overlay">${img(original.src,'同一历史任务的原始输入')}</div><div class="compare-divider"><span>↔</span></div><div class="compare-labels"><span>原图</span><span>历史结果</span></div><input type="range" min="0" max="100" value="50" aria-label="原图与结果对比分界" data-compare-slider></div>`}return `<div class="result-media">${o.type==='video'?`<video src="${esc(o.src)}" controls muted playsinline preload="metadata"></video>`:img(o.src,'已有真实生成结果')}<span class="history-mark">历史真实结果 · 非本次生成</span></div>`}
 function resultContent(scene){const d=draft(scene),s=sample(workflowMap[scene]);let top='';if(d.stage==='running')top=`<div class="progress-card"><h3>正在生成…</h3><p class="muted small">你可以继续调整下一次的参数。</p><div class="progress-bar"><span></span></div><div class="stage-labels"><span>✓ 素材就绪</span><span>● 生成中</span><span>○ 保存结果</span></div><div class="between" style="margin-top:16px"><small>状态演示 · 未提交模型任务</small>${button('取消本次演示','data-cancel-run')}</div></div>`;
 if(d.stage==='failed')top=`<div class="progress-card error"><h3>作品已生成，暂时没取回来</h3><p class="muted small">原任务和已有文件都保留了，可以再次取回。</p><div class="row" style="margin-top:16px">${button('重新取回作品','data-retrieve-preview','primary')}<small>提醒示例 · 不会重新生成</small></div></div>`;
 if(d.stage==='done')top=`<div class="progress-card"><h3>生成流程演示结束</h3><p class="muted small">${s.out?'下方是已有历史结果，这次没有生成新内容。':'这里只演示完成后的提醒，这次没有生成作品。'}</p></div>`;
 if(scene==='outpaint')top+=`<div class="pad-preview"><div class="pad-frame" id="pad-frame">${img(d.refs[0]?.src||'assets/coast.jpg','原图在扩展画布中的位置','id="pad-image"')}<span>画幅示意 · 新增区域待生成</span></div></div><p class="result-meta" id="pad-summary">${d.padRatio?'目标画幅 '+d.padRatio:'按四边实际像素设置扩展'}</p>`;
 return top+outputMarkup(scene)+(s.out?`<p class="result-meta">${dateLabel(s.job.started)} · ${taskName(s.job.workflow_id)} · 历史记录</p><div class="result-actions">${s.out.type==='image'&&s.refs.some(r=>r.kind==='image')?button(d.comparison?'查看结果':'与原图对比','data-compare',d.comparison?'active':''):''}<a href="${esc(s.out.src)}" download>${I('download')} 下载</a>${button('继续修改结果','data-continue','primary')}</div><div class="result-secondary">${button('↶ 恢复本次输入','data-restore-input')}${button('↻ 再抽一版','data-resample')}${button('查看本次设置','data-show-settings')}</div><p class="result-note">“恢复输入”取回原素材与设置；“继续修改”把当前结果作为新的原图。</p>`:'');
 }
 function filteredJobs(){let list=done.filter(j=>workFilter==='全部'||workFilter==='图像'&&j.outputs.some(o=>o.type==='image')||workFilter==='视频'&&j.outputs.some(o=>o.type==='video')||taskName(j.workflow_id).includes(workFilter));if(workQuery)list=list.filter(j=>[j.prompt,taskName(j.workflow_id),workNames.get(j.id)].join(' ').toLowerCase().includes(workQuery.toLowerCase()));if(timeFilter==='最近一周'){list=list.filter(j=>j.started>=Date.now()-7*86400000)}return list.sort((a,b)=>b.started-a.started).slice(0,36)}
 function works(){return `<div class="page">${header('我的作品','找到之前的版本，接着做。',`<input type="search" data-work-search value="${esc(workQuery)}" placeholder="搜索任务、作品名或描述" aria-label="搜索作品">`)}<div class="between"><div class="filter-row">${['全部','图像','视频','图片换衣','扩展画面'].map(t=>button(t,`data-work-filter="${t}"`,workFilter===t?'active':'')).join('')}</div><select data-time-filter aria-label="按时间筛选"><option ${timeFilter==='全部时间'?'selected':''}>全部时间</option><option ${timeFilter==='最近一周'?'selected':''}>最近一周</option></select></div><div class="works-grid" id="work-list">${workCards()}</div></div>`}
 function workCards(){return filteredJobs().map(j=>{const o=j.outputs[0],title=workNames.get(j.id)||taskName(j.workflow_id);return `<article class="work-card"><div class="work-image">${o.type==='video'?`<video src="${esc(o.src)}" muted playsinline preload="metadata"></video>`:img(o.src,title,'loading="lazy"')}<span class="pill">${o.type==='video'?'视频':'图像'}</span></div><div class="work-info"><div class="between"><strong>${esc(title)}</strong>${button('···',`data-rename="${j.id}" aria-label="重命名${esc(title)}"`,'subtle')}</div><p>${dateLabel(j.started)} · 真实历史记录</p><div class="row">${button('继续修改',`data-use-job="${j.id}"`)}<a href="${esc(o.src)}" download>下载</a>${button('查看',`data-view-job="${j.id}"`,'subtle')}</div></div></article>`}).join('')||'<div class="empty-state">没有找到作品。试试其他名称或筛选条件。</div>'}
 function assets(){return `<div class="page">${header('素材库','选择图片，带入对应的素材位置。',`<input type="search" aria-label="搜索素材" placeholder="搜索素材名称" data-asset-search>`)}<div class="status-note">${I('folder')}这里可试着选素材；示例图片已标注，选择只影响本次预览。</div><div class="works-grid" id="asset-grid">${assetPool.map((a,i)=>assetCard(a,i)).join('')}</div><div class="asset-toolbar"><span id="asset-count">已选 ${selectedAssets.size} 张图片</span>${button('带入创作 →','data-attach-assets '+(!selectedAssets.size?'disabled':''),'primary')}</div></div>`}
 function assetCard(a,i){return `<article class="work-card asset-card ${selectedAssets.has(i)?'selected':''}" data-asset-card="${i}" data-name="${esc(a.name||'素材图片')}"><div class="work-image">${img(a.src,a.name,'loading="lazy"')}</div><div class="work-info"><strong title="${esc(a.name)}">${esc(a.name||'素材图片')}</strong><p>图片 · ${a.previewExample?'示例图片':'来自历史任务'}</p>${button(selectedAssets.has(i)?'✓ 已选择':'+ 选择',`data-select-asset="${i}" aria-pressed="${selectedAssets.has(i)}"`)}</div></article>`}
 function inspiration(){return `<div class="page">${header('从一个案例开始','看清输入与结果，再复用适合你的创作方式。')}<div class="task-list-grid">${taskDefs.filter(t=>completed(t.id)).map(t=>{const s=sample(t.id),a=s.refs.find(r=>r.kind==='image');return `<article class="work-card"><div class="task-visual ${a&&s.out.type==='image'?'pair':''}" style="height:200px">${a&&s.out.type==='image'?img(a.src,'输入')+img(s.out.src,'结果')+'<span class="flow-arrow">→</span>':s.out.type==='video'?`<video src="${esc(s.out.src)}" muted playsinline preload="metadata"></video>`:img(sampleImage(t.id),t.title)}<span class="visual-label">真实历史案例</span></div><div class="work-info"><strong>${t.title}</strong><p>${t.desc}</p>${button('打开这个工具 →',`data-nav="${t.scene}"`)}</div></article>`}).join('')}<article class="work-card"><div class="work-image">${img('assets/coast.jpg','海岸灵感')}<span class="pill">示例配方</span></div><div class="work-info"><strong>清晨的海岸</strong><p>视觉灵感 · 没有原始生成记录</p>${button('使用示例描述 →','data-example-prompt')}</div></article></div></div>`}
 function settings(){return `<div class="page">${header('偏好设置','调整适合你的操作习惯。')}<div class="settings-list"><div class="setting-row"><div><strong>减少动态效果</strong><p>保留必要的状态反馈，减少过渡动画。</p></div><input type="checkbox" data-preference="reduce" aria-label="减少动态效果" ${preferences.reduce?'checked':''}></div><div class="setting-row"><div><strong>品牌与工作流管理</strong><p>Logo、工作流来源和接入状态归管理员维护。</p></div>${button('查看管理入口','data-admin')}</div><p class="settings-preview-hint">此页展示设置结构；切换仅在本次预览中生效。</p></div></div>`}
 function componentBlock(id,title,note,body,wide=false){return `<article class="component-demo ${wide?'span2':''}" data-component-category="${id}"><header><div><h3>${title}</h3><p>${note}</p></div><span class="pill">${id}</span></header>${body}</article>`}
 function libContext(key,id,fn){const w=sources.get(id);if(!w)return '<p>该工作流数据未加载</p>';if(!contextDrafts.has(key))contextDrafts.set(key,{w,d:{prompt:'保留主体，调整背景和光线。',refs:[],catalogValues:{},catalogSeedModes:{}}});const c=contextDrafts.get(key);return `<div class="control-context" data-context="${key}">${fn(w,c.d)}</div>`}
 function components(){let html='';html+=componentBlock('尺寸','画幅与像素总量','比例回答“长什么样”，像素总量回答“有多少像素”。',libContext('lib-size','local-card-3',(w,d)=>w.interface.controls.filter(f=>['ratio','resolution'].includes(f.kind)).map(f=>translatedField(d,f)).join('')));
 html+=componentBlock('输入','创作方式与变化方式','用户看含义，源字段保持原有取值。',libContext('lib-task','local-card-39',(w,d)=>translatedField(d,w.interface.controls.find(f=>f.kind==='task')))+libContext('lib-seed','local-card-3',(w,d)=>seedControls(w.interface.controls.filter(f=>f.kind==='seed'),d,{showTitle:false}).replaceAll('每次随机','每次不同').replaceAll('固定种子','固定本次')));
 html+=componentBlock('联动','条件生效与恢复默认','关闭功能时，相关数值禁用；修改后可恢复该项。',libContext('lib-strength','local-card-108',(w,d)=>w.interface.controls.filter(f=>['toggle','strength'].includes(f.kind)).map(f=>`<div data-field-wrap="${esc(f.id)}">${controlField(d,f)}${f.kind==='strength'?button('恢复默认 0.8',`data-reset-field="${esc(f.id)}"`,'reset-control'):''}</div>`).join('')));
 html+=componentBlock('输入','精确数值与源范围','保留工作流自己的单位，不统一改成百分比。',libContext('lib-values','local-card-13',(w,d)=>w.interface.controls.filter(f=>['resolution','color'].includes(f.kind)).map(f=>controlField(d,f)).join('')));
 html+=componentBlock('机位','单视角：拖动和精确输入','复用正式相机组件；机位示意不代表模型预览。',libContext('lib-camera','local-card-14',(w,d)=>catalogCommonPanel({...w,interface:{...w.interface,controls:w.interface.controls.filter(f=>f.kind==='camera')}},d)));
 html+=componentBlock('画幅','扩图：拖动与四边数值','左右和上下分别联动；输出尺寸与调色独立。',libContext('lib-outpaint','local-card-13',(w,d)=>catalogCommonPanel({...w,interface:{...w.interface,controls:w.interface.controls.filter(f=>f.kind==='outpaint')}},d)));
 html+=componentBlock('机位','九视角：一次看清全部机位','共同表头替代 9 次重复说明，27 个数值仍独立。',libContext('lib-multi','local-card-72',(w,d)=>catalogCommonPanel({...w,interface:{...w.interface,controls:w.interface.controls.filter(f=>f.kind==='camera')}},d)),true);
 const timeW=records.find(w=>w.interface.controls.some(f=>f.kind==='segment'&&f.type==='text'));
 const durationW=records.find(w=>w.interface.controls.some(f=>f.kind==='duration'&&f.derived));
 html+=componentBlock('时间','时间码与处理时长','使用正式分秒滚轮和全部/自定义选择。',libContext('lib-time',timeW.id,(w,d)=>controlField(d,w.interface.controls.find(f=>f.kind==='segment'&&f.type==='text')))+libContext('lib-duration',durationW.id,(w,d)=>controlField(d,w.interface.controls.find(f=>f.kind==='duration'&&f.derived))));
 html+=componentBlock('输入','文字、提示与错误','短说明解释用途；错误完整显示在对应输入旁。',`<div class="edit-section"><label>想修改什么？</label><textarea rows="3" placeholder="例如：把背景换成花园，保留人物与衣服。"></textarea><small>直接描述你希望看到的变化。</small></div><div class="edit-section"><label>不希望出现的内容 <small>选填</small></label><textarea rows="2" placeholder="例如：水印、文字"></textarea></div>`);
 html+=componentBlock('状态','完整状态，而不只是正常态','可以输入、切换和恢复，观察真实排版。',`<div class="state-gallery"><div class="state-sample"><label>空素材位</label><button class="upload-zone" data-state-upload>${I('plus')}<span>点击上传图片</span><small>选择后立即预览</small></button><p class="inline-error">还缺人物原图</p></div><div class="state-sample"><label>输出最长边</label><input type="number" value="5000" min="256" max="4096" data-demo-validation class="invalid" aria-label="验证示例输出最长边"><p class="inline-error" data-demo-error>请填写 256–4096 之间的像素值。</p>${button('恢复 1324','data-reset-demo','reset-control')}</div><div class="state-sample"><label>未开启时不可调整</label><input type="number" value="0.8" disabled aria-label="功能未开启时的强度"><small>先开启对应功能，才会使用此参数。</small></div><div class="state-sample"><label>正在准备素材</label><div class="progress-bar"><span></span></div><small>操作区保留位置，不跳动。</small></div><div class="state-sample"><label>服务暂时不可用</label><p class="inline-error">输入已保留，请重试。</p>${button('重试','data-state-retry')}</div><div class="state-sample"><label>长文案与键盘焦点</label><textarea rows="3" aria-label="长文案状态">保留原图中人物的衣服、发型与位置，仅调整窗外环境和照射方向，让光线自然地落在人物脸部。</textarea><small>按 Tab 移动焦点；文字不被截断。</small></div></div>`,true);
 html+=componentBlock('文字','字号与可读性对照','保留紫色视觉语言，主要信息不再压到 10–12px。',`<div class="comparison-mini"><div><small>原版</small><p class="old-caption">真实生成 · 算力卡计费</p><p style="font-size:12px;margin:10px 0">待编辑原图</p><button style="font-size:12px">生成</button></div><div><small>建议版</small><p class="new-caption">生成前说明费用情况</p><p style="font-size:14px;margin:10px 0">人物原图</p><button class="primary">生成 1 张</button></div></div>`);
 return `<div class="page component-page">${header('组件与状态','同一套正式组件，在真实任务中减少重复理解。',button('打开正式组件库','data-original-library','subtle'))}<div class="filter-row component-tabs">${['全部','尺寸','输入','联动','机位','画幅','时间','状态','文字'].map(t=>button(t,`data-component-filter="${t}"`,componentFilter===t?'active':'')).join('')}</div><div class="component-grid">${html}</div></div>`}
